describe('Data Table Responsive Stacking on Small Screens', () => {
  beforeEach(() => {
    cy.visit('/data-table');
  });

  it('should stack data table rows vertically on small screens', () => {
    // Intercept the API call to fetch table data
    cy.intercept('GET', '/api/data').as('fetchData');
    cy.wait('@fetchData');

    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Verify table has rows
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Verify table is in responsive mode (stacked)
    cy.get('[data-testid="data-table"]').should('have.class', 'responsive-table');

    // Verify table headers are visible and not hidden
    cy.get('[data-testid="table-header"]').should('be.visible');

    // Verify each row contains all expected data cells
    cy.get('[data-testid="table-row"]').each(($row) => {
      cy.wrap($row).should('contain', 'Name');
      cy.wrap($row).should('contain', 'Email');
      cy.wrap($row).should('contain', 'Status');
    });

    // Verify table is not in traditional table format
    cy.get('[data-testid="table-row"]').should('not.have.class', 'table-row-traditional');
  });

  it('should handle empty data table gracefully on small screens', () => {
    // Intercept the API call with empty data
    cy.intercept('GET', '/api/data', { body: { data: [] } }).as('fetchEmptyData');
    cy.wait('@fetchEmptyData');

    // Verify table container is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Verify no rows are displayed
    cy.get('[data-testid="table-row"]').should('not.exist');

    // Verify empty state message is displayed
    cy.get('[data-testid="empty-state-message"]')
      .should('be.visible')
      .should('contain', 'No data available');

    // Verify responsive class is still applied for consistency
    cy.get('[data-testid="data-table"]').should('have.class', 'responsive-table');

    // Verify empty state message is styled for small screens
    cy.get('[data-testid="empty-state-message"]')
      .should('have.css', 'font-size')
      .and('not.equal', '0px');
  });
});
